python3 -c "
import json
with open('contract_ground_truth') as f:
    for line in f:
        d=json.loads(line)
        for k,v in d['gold'].items():
            if not v['is_impossible'] and v['spans']:
                span = v['spans'][0]
                if isinstance(span, list):
                    print('list', span)
                elif isinstance(span, int):
                    print('int?', span)
                else:
                    print('str', repr(span))
                raise SystemExit
"
